// Sets an evening Sell (export) window on one slot. Dry run by default.
const env = $env;
const n = Number(env.SELL_SLOT || 6);
const start = env.SELL_START || '18:00';
const floor = Number(env.SELL_FLOOR_SOC || 50);
const enable = String(env.SELL_ENABLED || 'false') === 'true';
const dry = String(env.SELL_DRY_RUN ?? 'true').toLowerCase() !== 'false';
if (!(n >= 1 && n <= 6)) throw new Error('SELL_SLOT must be 1-6');
if (n === Number(env.GUARD_SLOT || 5)) throw new Error('SELL_SLOT must differ from GUARD_SLOT');
if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(start)) throw new Error('SELL_START must be HH:MM');
if (!(floor >= 20 && floor <= 100)) throw new Error('SELL_FLOOR_SOC must be 20-100');
// sellTime{n}En behaves differently by firmware: on some it is read-only via the cloud and must be set
// once on the inverter screen or in the app. Leave SELL_WRITE_ENABLE_FLAG=false unless you have tested it.
const calls = [
  { command: 'set_sell_time', params: { [`sellTime${n}`]: start } },
  { command: 'set_charge_cap', params: { [`cap${n}`]: floor } },
  { command: 'set_grid_charge', params: { [`time${n}On`]: '0', [`time${n}on`]: 'false' } },
];
if (String(env.SELL_WRITE_ENABLE_FLAG || 'false') === 'true') calls.push({ command: 'set_sell_enable', params: { [`sellTime${n}En`]: enable ? '1' : '0' } });
const out = [];
for (const c of calls) out.push(await this.helpers.httpRequest({ method: 'POST', url: env.SUNSYNK_CONTROL_URL || 'http://127.0.0.1:5678/webhook/sunsynk-control', json: true,
  headers: { [env.SUNSYNK_CONTROL_HEADER_NAME || 'X-Control-Key']: env.SUNSYNK_CONTROL_HEADER_VALUE || '' },
  body: { ...c, sn: env.SUNSYNK_INVERTER_SN, dry_run: dry || !enable } }));
return [{ json: { slot: n, start, floor, enabled: enable, dry_run: dry || !enable, results: out } }];
